        int x = q.front().first;
        int y = q.front().second;
        q.pop();

        if (x == n - 1 && y == n - 1) return true;

        for (int i = 0; i < 4; i++) {
            int nx = x + dx[i];
            int ny = y + dy[i];

            if (isValid(nx, ny, n) && !visited[nx][ny]) {
                if (grid[nx][ny] == d || grid[nx][ny] == 'S' || grid[nx][ny] == 'F') {
                    q.push({nx, ny});
                    visited[nx][ny] = true;
                }
            }
        }
    }

    return false;
}

