#include <bits/stdc++.h>

using namespace std;

const int MOD = 1e9 + 7;

int n, m;
vector<vector<int>> edges;

struct DisjointSet {
    vector<int> parent, rank;
    DisjointSet(int n) : parent(n), rank(n, 0) {
        for (int i = 0; i < n; i++)
            parent[i] = i;
    }
    int find(int x) {
        if (parent[x] != x)
            parent[x] = find(parent[x]);
        return parent[x];
    }
    void unionSets(int x, int y) {
        intfx = find(x);
        intfy = find(y);
        if (fx != fy) {
            if (rank[fx] < rank[fy])
                parent[fx] = fy;
            else if (rank[fx] > rank[fy])
                parent[fy] = fx;
            else {
                parent[fy] = fx;
                rank[fx]++;
            }
        }
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);

    cin >> n >> m;
