    for (int i = 0; i < n; i++) {
        int a = input[i][0];
        int b = input[i][1];

        if (dsu.find(a) != dsu.find(b)) {
            dsu.unionSets(a, b);
            used[i] = true;
        }
    }

    int ans = 1;
    for (int i = 0; i < n; i++) {
        if (used[i])
            ans = (ans * 2) % MOD;
    }

