int dp[200001][10];

int calculateLengthDP(int m) {
    for (int i = 0; i <= 9; ++i) {
        dp[0][i] = 1;
    }
    for (int i = 1; i <= m; ++i) {
        for (int j = 0; j <= 9; ++j) {
            int next = (j + 1) % 10;
            if (next == 0) {
                dp[i][j] = (dp[i - 1][0] + dp[i - 1][1]) % MOD;
            } else {
                dp[i][j] = dp[i - 1][next];
            }
        }
    }
    return 0;
}

