const int mod = 1e9 + 7;

int add(int a, int b) {
    return (a + b) % mod;
}

int sub(int a, int b) {
    return (a - b + mod) % mod;
}

int mul(int a, int b) {
    return (1LL * a * b) % mod;
}

int powmod(int a, int b) {
    int res = 1;
    while (b) {
        if (b & 1) {
            res = mul(res, a);
        }
        a = mul(a, a);
        b >>= 1;
    }
    return res;
}

int inv(int a) {
    return powmod(a, mod - 2);
}

