        u--, v--;
        adj[u].push_back(v);
        for (int j = 0; j < k; j++) {
            int x;
            cin >> x;
            x--;
            vision[u][v].push_back(x);
        }
    }
    bool found = false;
    for (int i = 0; i < n; i++) {
        path.clear();
        find_path(i, 0);
    }
    if (!found) cout << 0 << endl;
    for (int i = 1; i <= 2 * n; i++) {
        int ret = 0;
        for (int j = 0; j < n; j++) {
            ret = (ret + dfs(j, 1, i)) % MOD;
        }
        cout << ret << endl;
    }
    return 0;
}

