std::string to_base(int num, int base) {
    std::string res;
    while (num > 0) {
        int remainder = num % base;
        res = (remainder < 10 ? char('0' + remainder) : char('A' + (remainder - 10))) + res;
        num /= base;
    }
    return res;
}

int main() {
