    for (int i = 0; i < m; i++) {
        std::cin >> blocked[i];
    }

    std::vector<int> costs(k);
    for (int i = 0; i < k; i++) {
        std::cin >> costs[i];
    }

    int result = INT_MAX;
    for (int power = 1; power <= k; power++) {
        int cost = costs[power - 1];
        int count = 0;
        int position = 0;

        bool possible = true;
        while (position < n) {
            int nextPosition = position + power;
            while (m > 0 && blocked[m - 1] <= nextPosition) {
                m--;
                nextPosition++;
