            if (nextPosition > n) {
                if (position != 0 && m > 0 && blocked[m - 1] == n) {
                    possible = false;
                    break;
                } else {
                    count++;
                    break;
                }
            }

            position = nextPosition;
            count++;
        }

        if (possible) {
            result = std::min(result, count * cost);
        }
    }

    if (result == INT_MAX) {
        std::cout << -1 << std::endl;
    } else {
        std::cout << result << std::endl;
