bool isPossible(Vector A, Vector B, Vector C) {
    Vector tempA[4] = {
        {A.x, A.y},
        {A.y, -A.x},
        {-A.x, -A.y},
        {-A.y, A.x}
    };

    for (int i = 0; i < 4; i++) {
        int a = tempA[i].x;
        int b = tempA[i].y;
        int c = B.x - a;
        int d = B.y - b;

        if (c % C.x == 0 && d % C.y == 0 && c / C.x == d / C.y) return true;
    }

    return false;
}

