int depth[MAXN];
int cnt_leaf[MAXN];
int ans;

void dfs(int v, int p) {
    if (adj[v].empty()) {
        depth[v] = 0;
        cnt_leaf[v] = 1;
    } else {
        depth[v] = -1;
        cnt_leaf[v] = 0;
        for (auto u : adj[v]) {
            if (u == p) continue;
            dfs(u, v);
            depth[v] = max(depth[v], depth[u] + 1);
            cnt_leaf[v] += cnt_leaf[u];
        }
    }
}

