    for (int i = 0; i < best_c; i++) {
        for (char ch : c) {
            remain_a[ch]--;
        }
    }

    for (auto& pair : remain_a) {
        for (int i = 0; i < pair.second; i++) {
            cout << pair.first;
        }
    }

    return 0;
}

