int n;
int a[MAXN];

double f(double x) {
    double mx = 0.0;
    for (int i = 0; i < n; i++) {
        double s = 0.0;
        for (int j = i; j < n; j++) {
            s += a[j] - x;
            mx = max(mx, abs(s));
        }
    }
    return mx;
}

int main() {
