using namespace std;

const int MAXN = 1e6 + 5;

vector<int> p(MAXN), id(MAXN), sz(MAXN, 1);
vector<vector<int>> adj(MAXN);

int find(int x) {
    if (id[x] != x) id[x] = find(id[x]);
    return id[x];
}

void merge(int x, int y) {
    x = find(x); y = find(y);
    if (x == y) return;
    if (sz[x] > sz[y]) swap(x, y);
    id[x] = y; sz[y] += sz[x];
}

int main() {
    ios_base::sync_with_stdio(false); cin.tie(0);
    int n, m; cin >> n >> m;
    for (int i = 1; i <= n; i++) cin >> p[i], id[i] = i;
    for (int i = 0; i < m; i++) {
        int x, y; cin >> x >> y;
        adj[x].push_back(y); adj[y].push_back(x);
        merge(x, y);
    }

    vector<array<int, 2>> g[n + 1];
    for (int i = 1; i <= n; i++) {
        g[find(i)].push_back({p[i], i});
    }

    for (int i = 1; i <= n; i++) {
        if (g[i].empty()) continue;
        sort(g[i].begin(), g[i].end(), greater<array<int, 2>>());
        int idx = 0;
        for (int j : adj[i]) {
            if (find(j) != i) continue;
            p[j] = g[i][idx][0];
            idx++;
        }
    }

    for (int i = 1; i <= n; i++) cout << p[i] << " ";
    return 0;
}

#include <bits/stdc++.h>

using namespace std;

typedef long long ll;
typedef pair<int, int> pii;
typedef pair<ll, ll> pll;

const int MAXN = 1005;
const ll INF = 1e18;

struct Edge {
    int u, v, w;
    Edge(int _u = 0, int _v = 0, int _w = 0) : u(_u), v(_v), w(_w) {}
};

int n, m, L, s, t;
vector<Edge> edges;
ll dis[MAXN], ans[MAXN];
bool vis[MAXN];

void dijkstra(int src, ll dis[], bool findPath = false) {
    priority_queue<pll, vector<pll>, greater<pll>> pq;
    pq.push({0, src});

    for (int i = 0; i < n; i++) {
        dis[i] = INF;
        vis[i] = false;
    }

    dis[src] = 0;

    while (!pq.empty()) {
        int u = pq.top().second;
        pq.pop();

        if (vis[u]) continue;

        vis[u] = true;

        for (const Edge& e : edges) {
            int v = e.v;
            if (u == e.u && !vis[v]) {
                ll w = e.w;
                if (dis[v] > dis[u] + w) {
                    dis[v] = dis[u] + w;
                    pq.push({dis[v], v});
                    if (findPath) ans[e.u] = v;
                }
            }
        }
    }
}

int main() {
    cin >> n >> m >> L >> s >> t;

    for (int i = 0; i < m; i++) {
        int u, v, w;
        cin >> u >> v >> w;
        edges.push_back(Edge(u, v, w));
        edges.push_back(Edge(v, u, w));
    }

    dijkstra(s, dis);
    if (dis[t] >= L) {
        cout << "YES\n";
        for (int i = 0; i < m; i++) {
            Edge e = edges[i * 2];
            if (e.w == 0) e.w = 1;
            cout << e.u << " " << e.v << " " << e.w << "\n";
        }
        return 0;
    }

    dijkstra(t, dis, true);

    ll rem = L - dis[t];
    vector<int> ch;
    for (const Edge& e : edges) {
        if (e.w == 0) {
            ch.push_back(e.u);
            ch.push_back(e.v);
        }
    }

    sort(ch.begin(), ch.end());
    ch.erase(unique(ch.begin(), ch.end()), ch.end());

    ll cnt = 0;
    for (int i = 0; i < ch.size() && cnt < rem; i++) {
        int u = ch[i];
        for (const Edge& e : edges) {
            if (e.u == u && e.w == 0 && dis[e.v] + 1 == dis[u]) {
                cnt += 1;
                e.w = rem - cnt + 1;
                break;
            }
        }
    }

    if (cnt == rem) {
        cout << "YES\n";
        for (int i = 0; i < m; i++) {
            Edge e = edges[i * 2];
            cout << e.u << " " << e.v << " " << e.w << "\n";
        }
    } else {
        cout << "NO\n";
    }

    return 0;
}

