        if (dy < 0) {
            double parabolaLength = calculateParabolaLength(points[i - 1], points[i], v);
            length += parabolaLength;
        } else {
            double segmentLength = calculateDistance(points[i - 1], points[i]);
            length += segmentLength;
        }
    }

