        cout << x[i] << '\n';
    }
}

void swap(int i, int j) {
    swap(x[i], x[j]);
    swap(pos[i], pos[j]);
}

void bubbleSort() {
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n - 1; j++) {
            if (x[j] > x[j + 1]) {
                swap(j, j + 1);
            }
        }
    }
}

void bubbleSortK() {
    int cnt = 0;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n - 1; j++) {
            if (x[j] > x[j + 1]) {
                if (cnt < K) {
                    swap(j, j + 1);
                    cnt++;
                } else {
                    break;
                }
            }
        }
    }
}

