bool check(const string &s) {
    int x = 0, y = 0;
    for (char c : s) {
        bool found = false;
        if (x + 1 < n && table[x + 1][y] == c) {
            x++;
            found = true;
        }
        if (y + 1 < n && table[x][y + 1] == c) {
            y++;
            found = true;
        }
        if (!found) {
            return false;
        }
    }
    return true;
}

