        int cnt_a = count_a(s);
        int cnt_b = count_b(s);
        if (cnt_a > cnt_b) {
            ans = min(ans, "FIRST");
        } else if (cnt_a < cnt_b) {
            ans = min(ans, "SECOND");
        } else {
            ans = min(ans, "DRAW");
        }
        return;
    }
    if (step % 2 == 0) {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if ((i == 0 && j == 0 && s.empty()) || (i > 0 && s.back() == table[i - 1][j]) || (j > 0 && s.back() == table[i][j - 1])) {
                    string t = s + table[i][j];
                    if (check(t)) {
                        dfs(step + 1, t);
                    }
                }
            }
        }
    } else {
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if ((i == 0 && j == 0 && s.empty()) || (i > 0 && s.back() == table[i - 1][j]) || (j > 0 && s.back() == table[i][j - 1])) {
                    string t = s + table[i][j];
                    if (check(t)) {
                        dfs(step + 1, t);
                    }
                }
            }
        }
    }
}

