    scanf("%d", &n);
    for (int i = 1; i < n; i++) {
        int v, u;
        scanf("%d%d", &v, &u);
        --v, --u;
        g[v].push_back(u);
        g[u].push_back(v);
    }

    for (int v = 0; v < n; v++) {
        solve(v);
    }

    for (int v = 0; v < n; v++) {
        printf("%d ", can[v]);
    }
    puts("");

    return 0;
}

