int main() {
    scanf("%d%d%d", &n, &k, &M);
    for (int i = 1; i <= k; i++) scanf("%lld", &t[i]);
    sort(t + 1, t + k + 1);

    for (int i = 1; i <= k; i++) {
        long long s = 0;
        for (int j = 1; j <= i; j++) s += t[j];
        for (int j = 1; j <= n; j++) {
            if (s * j > M) break;
            g[j] = i * j;
            if (j * s <= M) g[j] += j;
        }
    }

    for (int i = 1; i <= n; i++) {
        for (int j = M; j >= 0; j--) {
            for (int p = 1; p <= k; p++) {
                long long s = 0;
                for (int q = 1; q <= p; q++) s += t[q];
                if (s * i > j) break;
                f[j] = max(f[j], f[j - s * i] + g[i]);
            }
        }
    }

    printf("%lld\n", f[M]);
    return 0;
}

#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>

using namespace std;

const int MAXN = 1005;
const double EPS = 1e-9;

struct Node {
    double fastTime;
    double slowTime;
    double prob;
};

int N, R;
Node levels[MAXN];

double memo[MAXN][MAXN];

double dp(int level, int timeLeft) {
    if (level == N) {
        return 0.0;
    }

    if (memo[level][timeLeft] > -EPS) {
        return memo[level][timeLeft];
    }

    double fastTime = levels[level].fastTime;
    double slowTime = levels[level].slowTime;
    double prob = levels[level].prob / 100.0;

    double resetTime = dp(0, R);

    double contFast = fastTime + dp(level + 1, timeLeft - fastTime);
    double contSlow = slowTime + dp(level + 1, timeLeft - slowTime);

    double result = prob * contFast + (1.0 - prob) * min(contSlow, resetTime + slowTime);
    memo[level][timeLeft] = result;

    return result;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(0);

    cin >> N >> R;

    for (int i = 0; i < N; ++i) {
        cin >> levels[i].fastTime >> levels[i].slowTime >> levels[i].prob;
    }

    for (int i = 0; i < MAXN; ++i) {
        for (int j = 0; j < MAXN; ++j) {
            memo[i][j] = -1.0;
        }
    }

    double result = dp(0, R);
    cout.precision(15);
    cout << result << endl;

    return 0;
}

