bool onCycle[MAX_N];
int parent[MAX_N];
int edgeId[MAX_N];
int discoveryTime[MAX_N];
int low[MAX_N];

int timer = 0;

void dfs(int u, int p) {
    visited[u] = true;
    discoveryTime[u] = timer;
    low[u] = timer;
    timer++;

    for (auto& e : adj[u]) {
        int v = e.first;
        int id = e.second;
        if (!visited[v]) {
            parent[v] = u;
            edgeId[v] = id;
            dfs(v, u);
            low[u] = min(low[u], low[v]);
            if (low[v] == discoveryTime[v] && parent[u] != v) {
                onCycle[id] = true;
            }
        } else if (v != p) {
            low[u] = min(low[u], discoveryTime[v]);
            if (discoveryTime[v] < discoveryTime[u]) {
                onCycle[edgeId[u]] = true;
                onCycle[id] = true;
            }
        }
    }
}

