bool can_reach(int start, int end) {
    int v = V;
    while (start < end) {
        int next = lower_bound(x + start, x + end + 1, x[start] + v) - x;
        if (next == end + 1) return false;
        v = V;
        start = next;
        if (v > 0) {
            v /= 2;
        }
    }
    return true;
}

