const int mod = 998244353;

long long fac[5005], inv[5005], n, s, r;

long long qpow(long long x, long long y) {
    long long res = 1;
    while (y) {
        if (y & 1) res = res * x % mod;
        x = x * x % mod;
        y >>= 1;
    }
    return res;
}

long long C(int x, int y) {
    if (x < y) return 0;
    return fac[x] * inv[y] % mod * inv[x - y] % mod;
}

int main() {
    std::cin >> n >> s >> r;
    fac[0] = inv[0] = 1;
    for (int i = 1; i <= 5000; i++) {
        fac[i] = fac[i - 1] * i % mod;
        inv[i] = qpow(fac[i], mod - 2);
    }
    long long ans = 0;
    for (int i = r; i <= s; i++) {
        long long q = 1;
        int t = i, now = s - i, cnt = n - 1;
        while (now >= t && cnt) {
            q = q * C(now + cnt - 1, cnt - 1) % mod;
            now -= t;
            cnt--;
        }
        if (cnt && now < t) q = 0;
        if (r == i) q = q * qpow(2, cnt) % mod;
        else q = q * qpow(2, cnt - 1) % mod;
        ans = (ans + q) % mod;
    }
    long long tmp = 0;
    for (int i = 0; i <= s; i++) {
        tmp = (tmp + C(i + n - 2, n - 2)) % mod;
    }
    tmp = qpow(tmp, mod - 2);
    std::cout << ans * tmp % mod << std::endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int MAXP = 17;

char str[100005];
int A[MAXP][MAXP];

int n, p;
vector<int> pos[MAXP];

bool canRemove(int c) {
    int m = pos[c].size();
    for (int i = 0; i < m; i++) {
        int p1 = pos[c][i];
        if (p1 == 0 || p1 == n - 1) continue;
        if (str[p1 - 1] == str[p1 + 1]) continue;
        int c1 = str[p1 - 1] - 'a', c2 = str[p1 + 1] - 'a';
        if (A[c1][c2] == 0) return false;
    }
    return true;
}

int maskToArr(int mask, int arr[]) {
    int idx = 0;
    for (int i = 0; i < p; i++) {
        if ((mask & (1 << i)) > 0) {
            arr[idx++] = i;
        }
    }
    return idx;
}

int checkMask(int mask) {
    int arr[MAXP], len;
    len = maskToArr(mask, arr);
    for (int i = 0; i < n; i++) {
        bool ok = false;
        for (int j = 0; j < len; j++) {
            if (str[i] - 'a' == arr[j]) {
                ok = true;
                break;
            }
        }
        if (!ok) return n + 1;
        for (int j = i + 1; j < n; j++) {
            if (str[j] == str[i]) break;
            bool ok2 = false;
            for (int k = 0; k < len; k++) {
                if (str[j] - 'a' == arr[k]) {
                    ok2 = true;
                    break;
                }
            }
            if (!ok2) return n + 1;
            int c1 = str[i] - 'a', c2 = str[j] - 'a';
            if (A[c1][c2] == 0) return n + 1;
        }
    }
    int cnt[MAXP] = {0};
    for (int i = 0; i < n; i++) {
        bool ok = false;
        for (int j = 0; j < len; j++) {
            if (str[i] - 'a' == arr[j]) {
                ok = true;
                break;
            }
        }
        if (ok) cnt[str[i] - 'a']++;
    }
    int ans = 0;
    for (int i = 0; i < p; i++) ans += cnt[i];
    return ans;
}

int main() {
    scanf("%d%d", &n, &p);
    scanf("%s", str);
    for (int i = 0; i < p; i++) {
        for (int j = 0; j < p; j++) {
            scanf("%d", &A[i][j]);
        }
    }
    for (int i = 0; i < n; i++) {
        pos[str[i] - 'a'].push_back(i);
    }
    int ans = n;
    for (int mask = 0; mask < (1 << p); mask++) {
        int tmp = checkMask(mask);
        if (tmp != n + 1) ans = min(ans, tmp);
    }
    printf("%d\n", ans);
    return 0;
}

