#include <iostream>
#include <vector>
#include <queue>
#include <limits>

const int INF = std::numeric_limits<int>::max();

struct Edge {
    int to;
    int cost;
};

int main() {
    int n, m;
    std::cin >> n >> m;

    std::vector<std::vector<Edge>> graph(n);
    for (int i = 0; i < m; ++i) {
        int u, v, cuv, cvu;
        std::cin >> u >> v >> cuv >> cvu;
        --u;
        --v;
        graph[u].push_back({v, cuv});
        graph[v].push_back({u, cvu});
    }

    int minCycleLength = INF;

    for (int s = 0; s < n; ++s) {
        std::vector<int> dist(n, -INF);
        std::vector<int> predecessor(n, -1);
        dist[s] = 0;

        for (int i = 0; i < n - 1; ++i) {
            bool updated = false;
            for (int u = 0; u < n; ++u) {
                for (const auto& edge : graph[u]) {
                    if (dist[u] + edge.cost > dist[edge.to]) {
                        dist[edge.to] = dist[u] + edge.cost;
                        predecessor[edge.to] = u;
                        updated = true;
                    }
                }
            }
            if (!updated) break;
        }

        for (int u = 0; u < n; ++u) {
            for (const auto& edge : graph[u]) {
                if (dist[u] + edge.cost > dist[edge.to]) {
                    int cycleLength = 0;
                    int v = edge.to;
                    while (v != u) {
                        ++cycleLength;
                        v = predecessor[v];
                    }
                    ++cycleLength;
                    minCycleLength = std::min(minCycleLength, cycleLength);
                }
            }
        }
    }

    if (minCycleLength == INF) {
        std::cout << 0 << std::endl;
    } else {
        std::cout << minCycleLength << std::endl;
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int N = 2e5 + 5;
typedef long long ll;

ll ans, sum;
bool vis[N];
int n, r[N], c[N], p[N];

void dfs(int x) {
    sum += (r[x] - 1);
    for (int i = 1; i <= n; i++) {
        if (!vis[i] && (r[i] == r[x] + 1) && ((c[x] + c[i]) % 2 == 0)) {
            if (c[x] < c[i]) {
                vis[i] = 1;
                dfs(i);
                return;
            }
        }
    }
    for (int i = 1; i <= n; i++) {
        if (!vis[i] && (r[i] == r[x] + 1) && ((c[x] + c[i] + 1) % 2 == 0)) {
            sum++;
            vis[i] = 1;
            dfs(i);
            return;
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0), cout.tie(0);
    cout << fixed << setprecision(10);
    int t;
    cin >> t;
    while (t--) {
        ans = 0, sum = 0;
        cin >> n;
        for (int i = 1; i <= n; i++) {
            cin >> r[i];
        }
        for (int i = 1; i <= n; i++) {
            cin >> c[i];
        }
        iota(p + 1, p + 1 + n, 1);
        sort(p + 1, p + 1 + n, [](int x, int y) { return r[x] < r[y]; });
        for (int i = 1; i <= n; i++) {
            if (!vis[i]) {
                dfs(i);
                ans += (sum - (r[p[i]] - 1));
                sum = 0;
            }
        }
        cout << ans << endl;
        memset(vis, 0, sizeof(vis));
    }
    return 0;
}
